INSERT INTO `schemes` VALUES (1,'KAR-SSP-POSTMATRIC','Post-Matric Scholarship for SC/ST and Backward Classes Students',NULL,1,'Social Welfare Department, Government of Karnataka','State Scholarship Directorate','Comprehensive educational scholarship providing 100% course fee reimbursement and monthly maintenance allowances for students pursuing higher education.','100% Course Fee Reimbursement + INR 1,200 to INR 3,500 Monthly Allowance directly credited via Aadhaar Bridge.','SCHOLARSHIP',25000.00,'Resident of Karnataka; Family annual income <= INR 2,50,000 for SC/ST or <= INR 1,00,000 for OBC; Enrolled in recognized university or college.','Apply online with college bonafide certificate, verified revenue income certificate, and Aadhaar-seeded bank account.','https://sw.karnataka.gov.in/schemes/postmatric','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-17 08:19:15','2026-11-17 08:19:15',NULL,'VERIFIED'),(2,'KAR-DIVYANGJAN-PENSION','Disability Maintenance & Assistive Aid Grant',NULL,2,'Directorate for the Empowerment of Differently Abled and Senior Citizens','Directorate for Empowerment of Differently Abled','Monthly pension and financial aid for citizens with physical or sensory disabilities ensuring dignified livelihood and social protection.','INR 2,000 per month direct credit to bank account plus free assistive aids and mobility equipment.','DIRECT_BENEFIT_TRANSFER',24000.00,'Permanent resident of Karnataka; Certified disability percentage of 40% or above from authorized medical board; Family income <= INR 1,50,000.','Upload Unique Disability ID (UDID) certificate, Aadhaar card, and residential proof.','https://sw.karnataka.gov.in/schemes/disability','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-17 08:19:15','2026-11-23 06:47:15',NULL,'VERIFIED'),(3,'KAR-SANDHYA-SURAKSHA','Sandhya Suraksha Senior Citizen Pension Scheme',NULL,3,'Revenue Department (Social Security and Pensions), Government of Karnataka','Social Security and Pensions Directorate','Social safety net pension for destitute senior citizens, agricultural laborers, and unorganized sector workers.','INR 1,200 per month direct benefit credit plus concessional state bus transport pass.','DIRECT_BENEFIT_TRANSFER',14400.00,'Age 65 years or above; Resident of Karnataka for at least 3 years; Combined family income <= INR 32,000 per year.','Submit age verification certificate, domicile certificate, and bank account details.','https://sw.karnataka.gov.in/schemes/sandhya-suraksha','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-17 08:19:15','2026-11-23 06:47:15',NULL,'VERIFIED'),(4,'KAR-INTERCASTE-MARRIAGE','Financial Incentive Scheme for Inter-Caste Marriages',NULL,4,'Social Welfare Department, Government of Karnataka','Social Welfare Directorate','One-time financial grant offered to newly wed couples where one spouse belongs to Scheduled Castes to foster social inclusion.','INR 2,50,000 incentive (INR 1,00,000 upfront cash transfer via DBT and INR 1,50,000 in government fixed deposit bonds).','FINANCIAL_ASSISTANCE',250000.00,'Either bride or groom must belong to Scheduled Caste; Marriage registered under Hindu Marriage Act; Annual income <= INR 5,00,000.','Submit registered marriage certificate, caste certificate of both partners, and joint bank account details.','https://sw.karnataka.gov.in/schemes/harmony','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-17 08:19:15','2026-11-23 06:47:35',NULL,'VERIFIED'),(5,'KAR-FLAG-GRUHA-LAKSHMI','Gruha Lakshmi Scheme',NULL,5,'Department of Women and Child Development, Government of Karnataka','Directorate of Women and Child Development','Flagship unconditional cash transfer granting direct financial assistance to the recognized woman head of every eligible household holding BPL, APL, or Antyodaya cards across Karnataka.','INR 2,000 per month paid directly through Aadhaar-seeded Direct Benefit Transfer (DBT).','MONTHLY_PENSION',2000.00,'Applicant must be the designated woman head of the family as recorded in BPL, APL or Antyodaya (AAY) ration cards. Neither the applicant nor her spouse may be government employees or income tax payees.','Submit Aadhaar card, ration card (BPL/APL/AAY), and Aadhaar-linked bank passbook details via Seva Sindhu or Grama One / Karnataka One centres.','https://sevasindhu.karnataka.gov.in/Gruhalakshmi','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Women, BPL households, APL households, Antyodaya households, Rural households','VERIFIED'),(6,'KAR-FLAG-GRUHA-JYOTHI','Gruha Jyothi Scheme',NULL,5,'Energy Department, Government of Karnataka','Electricity Supply Companies (BESCOM, HESCOM, GESCOM, MESCOM, CHESCOM)','Universal welfare guarantee offering zero-bill residential electricity up to 200 units per month for all domestic consumers whose average monthly consumption conforms to eligible entitlement limits.','100% subsidy on electricity consumption up to 200 units per month for domestic households.','SUBSIDY',1500.00,'All domestic household power connections in Karnataka with average annual consumption plus 10% entitlement under 200 units. Commercial or mixed connections are excluded.','Link domestic electricity consumer ID (Account ID) with Aadhaar and rental agreement or tenancy proof via Seva Sindhu portal.','https://sevasindhuservices.karnataka.gov.in/Gruhajyothi','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','BPL households, APL households, Antyodaya households, Rural households','VERIFIED'),(7,'KAR-FLAG-SHAKTI','Shakti Free Bus Travel Scheme',NULL,5,'Transport Department, Government of Karnataka','KSRTC, BMTC, NWKRTC, KKRTC','Mass mobility guarantee granting cost-free passenger transit on state-run non-luxury intra-state public buses for all domiciled women, girl students, and transgender citizens of Karnataka.','100% fare waiver on intra-state travel in city, ordinary, and express state transport buses.','SUBSIDY',1000.00,'All women, girl children, and transgender individuals domiciled in Karnataka. Travel is unrestricted within Karnataka\'s geographical borders on non-luxury transit.','Produce government-issued photo identity proof indicating Karnataka residency (such as Aadhaar, EPIC voter ID, or Shakti smart card) to conductor upon boarding.','https://ksrtc.karnataka.gov.in/shakti','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Women, Girl children, Students, Transgender','VERIFIED'),(8,'KAR-FLAG-ANNA-BHAGYA','Anna Bhagya Scheme',NULL,5,'Food, Civil Supplies and Consumer Affairs Department','Directorate of Food and Civil Supplies','Comprehensive nutritional guarantee supplying free food grains up to 10 kg and food kits per member per month for Antyodaya Anna Yojana (AAY) and Below Poverty Line (BPL) ration cardholder families.','Up to 10 kg food grains per person per month (plus DBT cash equivalent for additional grain quotas).','SUBSIDY',850.00,'Families holding valid BPL or Antyodaya (AAY) ration cards issued by the Department of Food and Civil Supplies, Government of Karnataka.','Avail food grains through biometric authentication at designated Fair Price Shops (FPS) using active ration card and Aadhaar seeding.','https://ahara.kar.nic.in','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','BPL households, Antyodaya households, Rural households','VERIFIED'),(9,'KAR-FLAG-YUVA-NIDHI','Yuva Nidhi Scheme',NULL,5,'Skill Development, Entrepreneurship and Livelihood Department','Karnataka Skill Development Corporation (KSDC)','Youth transition social security and skill-empowerment guarantee providing monthly unemployment allowances alongside free industry-aligned certification and apprenticeship training under Yuvanidhi Plus.','INR 3,000/month for degree graduates and INR 1,500/month for diploma holders for up to 2 years, plus skill training.','FINANCIAL_ASSISTANCE',3000.00,'Karnataka-domiciled graduates and diploma holders who graduated in eligible academic years and have remained unemployed or un-enrolled in higher education for over 180 days.','Register on Seva Sindhu with degree/diploma certificate, Nadakacheri residency certificate, Aadhaar, and Aadhaar-seeded bank account.','https://sevasindhugs.karnataka.gov.in/yuvanidhi','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Graduates, Diploma holders, Unemployed youth, Students','VERIFIED'),(10,'KAR-WCM-UDYOGINI','Udyogini Scheme',NULL,6,'Karnataka State Women\'s Development Corporation (KSWDC)','Department of Women and Child Development','Women entrepreneurship scheme facilitating subsidized institutional credit through commercial and cooperative banks for aspiring women to establish micro-enterprises and self-employment units.','Subsidized bank loans up to INR 3,00,000 with capital subsidy between 30% and 50% without collateral requirements.','FINANCIAL_ASSISTANCE',150000.00,'Women aged 18 to 55 years. Family income must not exceed INR 1,50,000 for general category; no income limit for SC/ST women.','Apply through KSWDC district offices or Seva Sindhu with project profile, caste certificate, income certificate, and bank details.','https://kswdc.karnataka.gov.in/udyogini','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Women, Entrepreneurs, SC beneficiaries, ST beneficiaries, OBC beneficiaries','VERIFIED'),(11,'KAR-WCM-BHAGYALAKSHMI','Bhagyalakshmi Scheme',NULL,6,'Department of Women and Child Development, Government of Karnataka','Directorate of Women and Child Development / LIC of India','Girl child survival and welfare bond scheme providing institutional financial security, health insurance, and educational endowments to uplift female sex-ratio and eliminate gender discrimination.','INR 1,00,000+ financial bond maturity benefit on attaining 18 years, annual scholarships, and health insurance.','FINANCIAL_ASSISTANCE',100000.00,'Girl children born in BPL families enrolled within one year of birth. Maximum of two girl children per eligible household.','Submit birth certificate, parents\' BPL ration card, and vaccination records to the local Anganwadi worker or Child Development Project Officer (CDPO).','https://wcd.karnataka.gov.in/bhagyalakshmi','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Girl children, Women, BPL households','VERIFIED'),(12,'KAR-WCM-MATRU-POORNA','Matru Poorna Scheme',NULL,6,'Department of Women and Child Development, Government of Karnataka','Integrated Child Development Services (ICDS)','Maternal and child nutrition mission providing hot, freshly cooked, micro-nutrient dense midday meals and IFA tablets daily to rural pregnant women and lactating mothers.','One free comprehensive hot cooked midday meal per day with eggs/sprouts, milk, and iron supplements throughout pregnancy and lactation.','SUBSIDY',1200.00,'All pregnant women and lactating mothers residing in rural and semi-urban catchment areas of Karnataka Anganwadi centres.','Register pregnancy with Mother and Child Protection (MCP) card at the nearest local Anganwadi centre.','https://wcd.karnataka.gov.in/matrupoorna','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Pregnant women, Lactating mothers, Women, Rural households','VERIFIED'),(13,'KAR-WCM-THAYI-BHAGYA','Thayi Bhagya & Prasoothi Araike Scheme',NULL,6,'Department of Health and Family Welfare, Government of Karnataka','National Health Mission (NHM) Karnataka','Safe motherhood intervention delivering cashless institutional delivery in empaneled private and secondary hospitals combined with direct cash incentives for nutrition during pregnancy.','100% cashless delivery care plus INR 6,000 cash assistance disbursed in tranches for maternal nutrition.','FINANCIAL_ASSISTANCE',6000.00,'Pregnant women belonging to BPL, SC, or ST families in designated high-priority taluks with no nearby government obstetric facilities.','Enrol with the local ASHA worker or Primary Health Centre (PHC) using Mother and Child Protection (MCP) tracking ID and BPL ration card.','https://hfw.karnataka.gov.in/thayibhagya','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Pregnant women, Lactating mothers, Women, BPL households, SC beneficiaries, ST beneficiaries','VERIFIED'),(14,'KAR-WCM-MADILU-KIT','Madilu Kit Scheme',NULL,6,'Department of Health and Family Welfare, Government of Karnataka','Directorate of Health and Family Welfare','Post-natal healthcare package distributing comprehensive newborn hygiene and mother comfort kits containing 19 essential maternal-infant care articles upon institutional delivery in government hospitals.','Post-natal kit with clothing, sterile baby wraps, mosquito nets, diapers, baby oil, and hygiene items valued at INR 2,500.','SUBSIDY',2500.00,'Mothers from BPL, SC, and ST families delivering babies in government district hospitals, taluk hospitals, or Community Health Centres (CHCs).','Conferred automatically upon discharge following institutional delivery in government hospitals upon presentation of BPL card.','https://hfw.karnataka.gov.in/madilu','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Pregnant women, Lactating mothers, Women, BPL households','VERIFIED'),(15,'KAR-WCM-SANTHWANA','Santhwana Scheme',NULL,6,'Karnataka State Women\'s Development Corporation (KSWDC)','Department of Women and Child Development','Integrated trauma and legal protection centers providing 24/7 emergency psycho-social counseling, temporary safe shelter, free legal aid, and rehabilitation assistance to women facing domestic distress.','Free emergency shelter, psychological counseling, legal aid, and financial relief grant up to INR 10,000 for medical/legal needs.','FINANCIAL_ASSISTANCE',10000.00,'Any woman or survivor of domestic violence, harassment, trafficking, or societal distress in Karnataka.','Contact the nearest Santhwana Centre located at taluk and district headquarters or call the Women\'s Helpline 181.','https://kswdc.karnataka.gov.in/santhwana','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Women, Vulnerable groups','VERIFIED'),(16,'KAR-WCM-DHANASHREE-CHETANA','Dhanashree & Chetana Scheme',NULL,6,'Karnataka State Women\'s Development Corporation (KSWDC)','Directorate of Women and Child Development','Targeted economic empowerment and micro-livelihood grant scheme providing seed grants and low-interest loans for HIV-affected women, devadasis, and socially marginalized vulnerable groups.','Self-employment grant of INR 45,000 to INR 50,000 combined with subsidized micro-credit and enterprise training.','FINANCIAL_ASSISTANCE',50000.00,'HIV-positive women, reformed devadasis, and distressed vulnerable women aged 18 to 55 residing permanently in Karnataka.','Apply via KSWDC district deputy director offices with medical documentation from ART centers or social status certificates.','https://kswdc.karnataka.gov.in/dhanashree','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Women, Vulnerable groups, SC beneficiaries, ST beneficiaries','VERIFIED'),(17,'KAR-AGR-RAITHA-VIDYA-NIDHI','Chief Minister Raitha Vidya Nidhi',NULL,7,'Agriculture Department, Government of Karnataka','Directorate of Agriculture & State Scholarship Portal (SSP)','Direct Benefit Transfer education scholarship awarding annual financial stipends to higher-education children of farmers, agricultural laborers, weavers, and fishermen across Karnataka.','Annual education grant of INR 2,000 to INR 11,000 credited directly to student bank accounts based on course level.','FINANCIAL_ASSISTANCE',11000.00,'Students enrolled in recognized secondary, PUC, ITI, diploma, degree, or postgraduate courses whose parent possesses a valid FRUITS Farmer ID.','Apply online through State Scholarship Portal (SSP Karnataka) citing Parent FRUITS Farmer Identification (FID).','https://ssp.postmatric.karnataka.gov.in','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Students, Farmers, Agricultural labourers, Rural households','VERIFIED'),(18,'KAR-AGR-GANGA-KALYANA','Ganga Kalyana Scheme',NULL,7,'Social Welfare Department & Backward Classes Welfare Department','Dr. B.R. Ambedkar Development Corporation / KMDC / D. Devaraj Urs Corporation','Perennial irrigation development scheme funding free borewell drilling, submersible pump sets, and energized power connections for small and marginal farmers belonging to SC, ST, and backward communities.','Full financial grant up to INR 3,50,000 to INR 4,00,000 covering borewell drilling, motor installation, and electrification.','FINANCIAL_ASSISTANCE',350000.00,'Small or marginal farmers belonging to SC, ST, backward classes, or religious minorities possessing contiguous agricultural land (minimum 1.2 to 2 acres).','Apply through Seva Sindhu or respective Development Corporation portals with RTC pahani records, caste/income certificates, and small farmer certificate.','https://adcl.karnataka.gov.in/gangakalyana','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Farmers, SC beneficiaries, ST beneficiaries, OBC beneficiaries, Minority communities','VERIFIED'),(19,'KAR-AGR-KRISHI-BHAGYA','Krishi Bhagya Scheme',NULL,7,'Agriculture Department, Government of Karnataka','Directorate of Agriculture','Climate-resilient dryland farming scheme subsidizing on-farm rainwater harvesting ponds with polythene lining, diesel/solar lift pumps, and polyhouse micro-irrigation installations.','80% to 90% capital subsidy on farm pond excavation, protective plastic lining, diesel pump sets, and shade nets.','SUBSIDY',125000.00,'Farmers in designated drought-prone and rainfed dryland agro-climatic zones of Karnataka with minimum agricultural landholding.','Apply at the local Raitha Samparka Kendra (RSK) with land RTC records, Aadhaar, and FRUITS Farmer ID.','https://raitamitra.karnataka.gov.in/krishibhagya','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Farmers, Rural households','VERIFIED'),(20,'KAR-AGR-MICRO-IRRIGATION','Farmer Irrigation Assistance Scheme (Micro-Irrigation)',NULL,7,'Horticulture Department & Agriculture Department','Directorate of Horticulture','Precision water-management assistance providing heavy capital subsidies for installing approved drip and sprinkler micro-irrigation systems to maximize crop yield per drop.','90% subsidy for SC/ST small farmers and 75% subsidy for general category farmers on certified micro-irrigation equipment.','SUBSIDY',65000.00,'Farmers cultivating horticultural or agricultural crops with an operational water source (borewell/canal/well) and registered land RTC records.','Apply via the Horticulture Department or Raitha Samparka Kendra with land records, water source certificate, and FRUITS FID.','https://horticulturedir.karnataka.gov.in','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Farmers, SC beneficiaries, ST beneficiaries, Rural households','VERIFIED'),(21,'KAR-AGR-KRUSHI-ARANYA','Krushi Aranya Protsaha Yojane (KAPY)',NULL,7,'Forest, Ecology and Environment Department, Government of Karnataka','Karnataka Forest Department','Agro-forestry incentive encouraging farmers to plant and nurture diverse timber, fruit, and bamboo saplings on bunds and farm borders through recurring survival incentive stipends.','INR 125 cash incentive per surviving sapling distributed in tranches over 3 years (INR 35 in year 1, INR 40 in year 2, INR 50 in year 3).','FINANCIAL_ASSISTANCE',125.00,'All farmers and landowners in Karnataka who purchase subsidized tree saplings from the Forest Department and plant them on agricultural land.','Obtain saplings at nominal cost (INR 1 to 3) from Forest Department nurseries and register bank details with the Range Forest Officer (RFO).','https://aranya.gov.in/kapy','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Farmers, Rural households','VERIFIED'),(22,'KAR-AGR-YESHASVINI','Yeshasvini Cooperative Health Insurance Scheme',NULL,7,'Cooperation Department, Government of Karnataka','Yeshasvini Cooperative Farmers Health Care Trust','Pioneering cooperative healthcare program delivering cashless surgical procedures and inpatient treatment through empaneled network hospitals for cooperative society members and rural families.','Cashless hospitalization and surgical treatment coverage up to INR 5,00,000 per family per year across 1,650+ approved surgical procedures.','SUBSIDY',500000.00,'Members of Rural and Urban Cooperative Societies, Self-Help Groups, or Stree Shakthi groups in Karnataka who have been active members for at least 3 months.','Enrol through respective primary agricultural credit societies (PACS) or cooperative societies by paying nominal annual contribution.','https://yeshasvini.karnataka.gov.in','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Farmers, Cooperative members, Rural households','VERIFIED'),(23,'KAR-AGR-RAITHA-SIRI','Raitha Siri Scheme',NULL,7,'Agriculture Department, Government of Karnataka','Directorate of Agriculture','Millets promotion incentive offering direct cash assistance per hectare through DBT to encourage sustainable cultivation of nutritious minor millets including Ragi, Jowar, Foxtail, and Little millet.','Direct financial assistance of INR 10,000 per hectare (up to maximum 2 hectares) credited directly to farmer bank accounts.','FINANCIAL_ASSISTANCE',10000.00,'Farmers cultivating recognized minor millets in Karnataka verified through the Farmer Registration and Unified Beneficiary Information System (FRUITS).','Register crop survey data on FRUITS portal and verify through the local Raitha Samparka Kendra.','https://raitamitra.karnataka.gov.in/raithasiri','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Farmers, Rural households','VERIFIED'),(24,'KAR-EDU-ARIVU-LOAN','Arivu Education Loan Scheme',NULL,8,'Minorities Welfare Department & Backward Classes Welfare Department','Karnataka Minorities Development Corporation (KMDC) / D. Devaraj Urs Corporation','Concessional higher education financing scheme providing low-interest loans for meritorious students from religious minorities and backward classes pursuing medical, engineering, and professional courses.','Low-interest educational loans up to INR 5,00,000 per year at 2% simple interest for professional degree programs.','FINANCIAL_ASSISTANCE',500000.00,'Students belonging to religious minorities or backward classes selected through KEA/CET/NEET with family income under INR 3,50,000.','Apply online through KMDC or D. Devaraj Urs portal with CET/NEET admission slip, fee structure, and income/caste certificates.','https://kmdc.karnataka.gov.in/arivu','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Students, Minority communities, OBC beneficiaries','VERIFIED'),(25,'KAR-EDU-VIDYASIRI','Vidyasiri (Food & Accommodation Stipend)',NULL,8,'Backward Classes Welfare Department, Government of Karnataka','Directorate of Backward Classes Welfare','Hostel alternative stipend providing monthly cash allowances for food and lodging to post-matric backward classes students who are unable to secure admission into government student hostels.','INR 1,500 per month stipend for 10 months (INR 15,000 per academic year) credited directly via DBT.','FINANCIAL_ASSISTANCE',15000.00,'Post-matric students belonging to SC, ST, OBC, Cat-1, 2A, 2B, 3A, 3B residing at least 5 km away from college and without government hostel accommodation.','Submit application through State Scholarship Portal (SSP) post-matric module with college admission verification.','https://ssp.postmatric.karnataka.gov.in/vidyasiri','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Students, OBC beneficiaries, SC beneficiaries, ST beneficiaries','VERIFIED'),(26,'KAR-EDU-PRABHUDDHA-AMBEDKAR','Prabuddha & Dr. B.R. Ambedkar Overseas Scholarships',NULL,4,'Social Welfare Department, Government of Karnataka','Social Welfare Directorate','Prestigious international scholarship fully funding postgraduate and doctoral studies in top global universities for meritorious students belonging to SC, ST, and minority communities.','100% tuition fee coverage plus living allowance and economy airfare up to INR 20,00,000 per year (up to INR 50,00,000 total course funding).','FINANCIAL_ASSISTANCE',2000000.00,'Karnataka-domiciled SC/ST students with minimum 60% in undergraduate degree admitted to QS World Top-ranked foreign universities.','Apply via Social Welfare Department overseas portal with foreign university unconditional offer letter, GRE/IELTS score, and passport.','https://sw.karnataka.gov.in/overseas','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-23 06:47:15','Students, SC beneficiaries, ST beneficiaries, Graduates','VERIFIED'),(27,'KAR-EDU-ELEVATE','ELEVATE & ELEVATE NxT Startup Grants',NULL,1,'Department of Electronics, IT, Bt and S&T, Government of Karnataka','Startup Karnataka / KITS','Pre-seed equity-free innovation grants and accelerator funding for early-stage tech, biotech, social-impact, and deep-tech startups founded by young innovators in Karnataka.','Equity-free funding up to INR 50,00,000 (and up to INR 1 Crore under ELEVATE NxT for deep-tech / SC-ST founders), plus incubation mentorship.','FINANCIAL_ASSISTANCE',5000000.00,'Registered startups in Karnataka with innovative MVP/POC, incorporated less than 10 years, with registered office in Karnataka.','Apply during annual call for proposals on Startup Karnataka portal; undergo pitch evaluation before Grand Jury.','https://startup.karnataka.gov.in/elevate','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-23 06:47:15','Entrepreneurs, Unemployed youth, Graduates','VERIFIED'),(28,'KAR-EDU-RAJIV-GANDHI-ENTREPRENEUR','Rajiv Gandhi Entrepreneurship Program',NULL,1,'Department of Electronics, IT, Bt and S&T, Government of Karnataka','Karnataka Innovation and Technology Society (KITS)','Young innovator fellowship providing monthly stipends and institutional incubation support to science and technology graduates building science-based prototype enterprises.','INR 25,000 monthly fellowship allowance for 12 months (total INR 3,00,000) alongside university incubation access.','FINANCIAL_ASSISTANCE',300000.00,'Graduates in engineering, technology, biotechnology, or applied sciences from recognized Karnataka universities with validated prototype concepts.','Submit research-to-market proposal through KITS or partner university technology business incubators.','https://startup.karnataka.gov.in/rgep','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-23 06:47:15','Graduates, Entrepreneurs, Unemployed youth, Students','VERIFIED'),(29,'KAR-LAB-KBOCWWB','Karnataka Construction Workers (KBOCWWB) Schemes',NULL,9,'Labour Department, Government of Karnataka','Karnataka Building and Other Construction Workers Welfare Board','Comprehensive welfare umbrella providing monthly pensions, medical treatment reimbursement, accident relief, marriage assistance, and child education grants for registered construction workers.','Monthly pension of INR 3,000 post age 60, marriage grant INR 50,000, education grants up to INR 25,000/yr, and accident relief up to INR 5,00,000.','FINANCIAL_ASSISTANCE',50000.00,'Construction workers aged 18 to 60 who have engaged in building or construction work for at least 90 days in the preceding 12 months.','Register as a construction worker on the KBOCWWB portal or Seva Sindhu with 90-day work certificate and employer confirmation.','https://kbocwwb.karnataka.gov.in','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Construction workers, Unorganized workers, BPL households','VERIFIED'),(30,'KAR-LAB-GIG-WORKERS-INSURANCE','Karnataka State Gig Workers Insurance Scheme',NULL,9,'Labour Department, Government of Karnataka','Karnataka State Unorganized Workers Social Security Board (KSUWSSB)','Groundbreaking social protection program delivering state-funded accidental and life insurance coverage to app-based gig and delivery workers operating on digital aggregator platforms.','INR 4,00,000 total insurance coverage (INR 2,00,000 accidental death/total disability + INR 2,00,000 hospital expense reimbursement).','SUBSIDY',400000.00,'Platform-based delivery executives and drivers registered with Swiggy, Zomato, Uber, Ola, Dunzo, Amazon, etc., operating in Karnataka.','Register on the Seva Sindhu gig worker portal with platform onboarding ID, driving license, and Aadhaar card.','https://labour.karnataka.gov.in/gigworkers','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Gig workers, Unorganized workers, Unemployed youth','VERIFIED'),(31,'KAR-LAB-AMBEDKAR-KARMIKA','Ambedkar Karmika Sahaya Hastha',NULL,9,'Labour Department, Government of Karnataka','Karnataka State Unorganized Workers Social Security Board','Welfare assistance initiative issuing biometric smart cards, accident relief cover, and occupation-specific safety toolkits to workers in unorganized, domestic, and manual trades.','Biometric smart identity card, INR 2,00,000 accident relief, and free trade toolkit valued up to INR 10,000.','FINANCIAL_ASSISTANCE',10000.00,'Unorganized workers aged 18 to 60 across recognized trades (tailors, domestic servants, mechanics, dhobis, barbers) not covered under EPF/ESI.','Register at Karnataka One or Grama One center with trade proof, Aadhaar, and bank passbook.','https://labour.karnataka.gov.in/unorganized','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Unorganized workers, BPL households, SC beneficiaries, ST beneficiaries','VERIFIED'),(32,'KAR-LAB-SWAVALAMBI-SARATHI','Swavalambi Sarathi Scheme',NULL,4,'Social Welfare Department & Backward Classes Welfare Department','Dr. B.R. Ambedkar / D. Devaraj Urs / KMDC Corporations','Self-employment mobility initiative providing up to 75% capital subsidy for unemployed marginalized youth to purchase four-wheeler commercial yellow-board cabs, autos, or goods vehicles.','Capital subsidy of 50% to 75% of vehicle cost (up to INR 3,00,000 to INR 4,00,000 subsidy) with remaining cost financed via bank loan.','FINANCIAL_ASSISTANCE',350000.00,'Unemployed youth aged 21 to 45 belonging to SC, ST, backward classes, or religious minorities holding a valid commercial transport driving license.','Apply through respective Corporation portals with valid driving license, badge, caste certificate, and vehicle quotation.','https://adcl.karnataka.gov.in/swavalambi','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-23 06:47:15','Unemployed youth, SC beneficiaries, ST beneficiaries, OBC beneficiaries, Minority communities','VERIFIED'),(33,'KAR-LAB-SHRAMA-SHAKTHI','Shrama Shakthi Loan Scheme',NULL,8,'Minorities Welfare Department, Government of Karnataka','Karnataka Minorities Development Corporation (KMDC)','Financial assistance program extending subsidized micro-business loans to religious minority artisans, craftspeople, and small vendors to expand working capital and upgrade tool sets.','INR 50,000 loan at low 4% simple interest per annum, including a 50% back-ended capital subsidy of INR 25,000 upon timely repayment.','FINANCIAL_ASSISTANCE',50000.00,'Artisans and small vendors from Muslim, Christian, Jain, Buddhist, Sikh, or Parsi communities with annual family income under INR 1,50,000.','Apply via KMDC online portal or district offices with minority certificate, artisan trade proof, and Aadhaar.','https://kmdc.karnataka.gov.in/shramashakthi','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-23 06:47:15','Minority communities, Entrepreneurs, Unorganized workers','VERIFIED'),(34,'KAR-LAB-BASAVA-AMBEDKAR-NIVAS','Basava Vasati & Dr. B.R. Ambedkar Nivas Yojane',NULL,9,'Housing Department, Government of Karnataka','Rajiv Gandhi Housing Corporation Limited (RGHCL)','Universal housing mission delivering unit-cost financial grants to homeless rural families and SC/ST households to construct permanent pucca concrete houses with sanitation facilities.','Unit grant of INR 1,50,000 for general category and INR 2,00,000 for SC/ST families released in geo-tagged construction stages.','FINANCIAL_ASSISTANCE',200000.00,'Homeless or katcha-house resident rural families in Karnataka whose annual family income is below INR 32,000 and possessing site ownership documents.','Selected through Gram Sabha resolution; registered via RGHCL Ashraya portal with site title deeds and GPS photos.','https://ashraya.karnataka.gov.in','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-18 07:56:50','Homeless families, BPL households, SC beneficiaries, ST beneficiaries, Rural households','VERIFIED'),(35,'KAR-LAB-GRUHA-AROGYA','Gruha Arogya Yojana',NULL,6,'Department of Health and Family Welfare, Government of Karnataka','National Health Mission (NHM) Karnataka','Proactive doorstep public health screening and medicine distribution program delivering home checkups, chronic disease detection, and free 30-day supplies of essential non-communicable disease medications.','Free home health screenings for hypertension, diabetes, and cancers, plus 30-day free doorstep delivery of prescribed chronic medications.','SUBSIDY',1800.00,'All Karnataka citizens aged 30 and above, particularly vulnerable rural residents and elderly citizens.','Conducted door-to-door by community ASHA workers and Community Health Officers (CHOs) with mobile health tablets.','https://hfw.karnataka.gov.in/gruhaarogya','2026-01-01','2026-12-31','PUBLISHED','ONLINE_FORM',1,'SYSTEM_ADMIN','2026-11-18 07:56:50','2026-11-23 06:47:15','Rural households, BPL households, Vulnerable groups','VERIFIED');
